graphy": null, "status": "draft", "id": "0c5a5869-dc9f-5893-b3a4-cbe279406582"}, {"name": "许彬", "aliases": ["許彬"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，许彬升任礼部右侍郎，兼翰林学士并入阁。", "biography": null, "status": "draft", "id": "a9df097f-7235-5c19-b28f-89082c141669"}, {"name": "薛瑄", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰8年（1457年）正月，薛瑄升任礼部右侍郎，兼翰林学士并入阁。", "biography": null, "status": "draft", "id": "db674166-9da7-54f1-a2f6-4de92f9842f6"}, {"name": "曹钦", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代起兵者。天顺5年（年号对照1461年），本表记录了曹钦的活动。", "biography": null, "status": "draft", "id": "4667ba2d-c9e8-5b4f-8a95-cb0080e144eb"}, {"name": "陈循", "aliases": ["陳循"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統9年（1444年）四月，陈循以翰林学士身份入直内阁。", "biography": null, "status": "draft", "id": "b5542e79-ef69-5435-9fe8-6c263bd5be96"}, {"name": "江渊", "aliases": ["江淵"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰元年（1450年）八月，江渊以刑部侍郎兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "4c319c1c-fb8c-52d1-82ca-fd1b4cdab14e"}, {"name": "俞士悦", "aliases": ["俞士悅"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统14年（年号对照1449年）十一月，俞士悦出任刑部尚书。", "biography": null, "status": "draft", "id": "f0f2870b-2261-50d4-8597-70bf7126169b"}, {"name": "萧镃", "aliases": ["蕭鎡"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰2年（1451年）十二月，萧镃以国子监祭酒兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "4e43d816-8596-5052-bfa1-6fa5761eee83"}, {"name": "商辂", "aliases": ["商輅"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統14年（1449年）八月，商辂以翰林修撰身份入阁。", "biography": null, "status": "draft", "id": "a6a9b79a-e654-56d7-85ce-a79e61f4c5f2"}, {"name": "孙镗（明代怀宁侯）", "aliases": ["都督孫鏜"], "era": "明", "birth_year": null, "death_year": null, "description": "孙镗（明代怀宁侯）奉命