tus": "draft", "id": "71fde383-1de5-538d-bb25-2cc9e4cc7d1c"}, {"name": "朱见潾", "aliases": ["朱见清", "榮王", "德莊王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见潾受封荣王。", "biography": null, "status": "draft", "id": "7b3ab777-130c-52de-adb1-5af62c3c97b3"}, {"name": "朱见澍", "aliases": ["秀懷王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见澍获封秀王。", "biography": null, "status": "draft", "id": "fed1abbd-fadc-5dd6-8662-5d245623ed7b"}, {"name": "朱见泽", "aliases": ["崇簡王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见泽获封崇王。", "biography": null, "status": "draft", "id": "1a482b7e-c7bf-59a1-86a6-c303454d63ff"}, {"name": "朱见浚", "aliases": ["吉簡王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见浚获封吉王。", "biography": null, "status": "draft", "id": "cf2ae2aa-c720-5a94-93a3-e2394ce82330"}, {"name": "孛来", "aliases": ["孛來"], "era": "明", "birth_year": null, "death_year": null, "description": "孛来率部进攻宁夏。", "biography": null, "status": "draft", "id": "002b89e8-be8d-5e7f-9365-e517b45d0c6d"}, {"name": "杨瑄", "aliases": ["御史楊瑄"], "era": "明", "birth_year": null, "death_year": null, "description": "杨瑄被下狱。", "biography": null, "status": "draft", "id": "5acf0349-b7e8-5480-b41d-13effe94fb2b"}, {"name": "张鹏", "aliases": ["張鵬"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，成化18年（年号对照1482年）三月，张鹏出任兵部尚书。", "biography": null, "status": "draft", "id": "5743e89d-eab1-5980-9a93-a3230e8a0856"}, {"name": "耿九畴", "aliases": ["耿九疇"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）三月，耿九畴出任右都御史。", "biography": null, "status": "draft", "id": "72d75593-924e-5fc5-b5f5-4bf88dd1343a"}, {"name": "罗绮", "aliases": ["羅綺"], "era": "明", "birth_year": null, "death_year": null, "description": "罗绮奉命出使瓦剌。", "biography": null, "status": "draft", "id": "8da49676-7c80-5c15-ac93-083195df47cf"}, {"name": "吕原", "aliases": ["呂原"], "era": "明", "birth_year": null, "death_year": n