on_precision": "unknown", "location_note": null, "status": "draft", "id": "5ebc3c1b-abc0-5ee6-a5ca-5ae09f54d63a"}, {"title": "江渊被贬往边地戍守", "description": "天顺元年（年号对照1457年）正月，江渊被贬往边地戍守。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年（年号对照1457年）正月；公元年核为1457年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "81d13ad2-c5ac-5905-a388-34ae77066fd8"}, {"title": "俞士悦被贬往边地戍守", "description": "天顺元年（年号对照1457年）正月，俞士悦被贬往边地戍守。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年（年号对照1457年）正月；公元年核为1457年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "366f03ae-0554-54f9-b12f-97afab4e2cd7"}, {"title": "萧镃被革职为民", "description": "景泰8年（1457年）正月，萧镃被革职为民。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "8d4916be-f72b-5f8a-bb63-aa91fe51037c"}, {"title": "商辂被革职为民", "description": "景泰8年（1457年）正月，商辂被革职为民。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）正月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "f95d5c43-a403-5d11-b94b-e4777c93343e"}, {"title": "明廷再次按迎复之功封赏孙镗、董兴等人", "description": "天顺元年正月己丑，明廷再次封赏迎奉英宗复位者，封孙镗为怀宁伯、董兴为海宁伯，升钦天监正汤序为礼部右侍郎。本纪记晋级的官员、舍人和军士共有三千余人。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年正月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c6cbd157-2f59-5fb0-817a-24a0e5e6bddc"}, {"title": "明廷撤销巡抚和提督官", "description": "天顺元年正月辛卯，朝廷撤销巡抚和提督官。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年正月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9542fbf3-2370-5a38-b427-d84ba28a50d3"}, {"title": "明廷公布被其认定为于谦同党者名单", "description": "天顺元年正月壬辰，明廷张榜公布被朝廷认定为于谦同党者的名单。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年正月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "285fc2f6-a809-5394-960b-4485d099458b"}, {"title": "明廷处死昌平侯杨俊", "description": "天顺元年正月甲午，明廷处死昌平侯杨俊。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年正月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ef6bba8e-4dcd-5052-8c78-562a139387d4"}, {"title": "明英宗废朱祁钰为郕王并迁往西内", "description": "景泰八年二月乙未，复位的明英宗朱祁镇废朱祁钰为郕王，将他迁往西内，原为皇太后的吴氏等恢复旧封号。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05b22b67-1c38-51eb-a3cc-7f724ef1e85f"}, {"title": "高谷退休", "description": "景泰8年（1457年）二月，高谷退休。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ea2df4ac-cb61-5591-820a-56028a593d75"}, {"title": "汤序请求废去景泰年号，明英宗不准", "description": "天顺元年二月，汤序上奏请求抹去已经使用过的景泰年号，明英宗没有批准。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "51012445-0148-5dd3-8baf-066542451aac"}, {"title": "李贤以礼部侍郎兼翰林学士身份入阁", "description": "景泰8年（1457年）二月，李贤以礼部侍郎兼翰林学士身份入阁。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "40d34138-9d4a-57b8-b7a7-9bf95ce4d68f"}, {"title": "明廷处死都督范广", "description": "天顺元年二月癸卯条记，明廷处死都督范广。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b8042777-8dff-51fd-807e-26b5faf4bd89"}, {"title": "柳溥在广西击败当地反抗武装", "description": "天顺元年二月戊申，明军将领柳溥在广西击败当地反抗明廷的武装。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年二月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07059be3-6c63-54c3-b7dc-a74f5abb61d7"}, {"title": "朱祁钰在西宫去世", "description": "景泰八年二月癸丑，被废为郕王的朱祁钰在西宫去世。《明史》本纪记其年三十。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年二月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1663eb32-d37a-57cf-a0c8-034e98047ac7"}, {"title": "方瑛、石璞在湖广击败起事苗民", "description": "天顺元年二月戊午，方瑛、石璞在湖广率军击败起事的苗民。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年二月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a66df965-620b-5610-a837-fdb0be047baf"}, {"title": "明廷召石璞返回", "description": "天顺元年二月，石璞在湖广与方瑛作战获胜后，明廷召他返回。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2c8cec93-852e-5747-956f-499ef486e5ee"}, {"title": "明廷豁免南直隶灾区秋粮", "description": "天顺元年二月壬戌，朝廷免除南直隶灾区应缴的秋粮。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年二月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e75c8125-e442-53e1-b21b-4472d98c5253"}, {"title": "明英宗恢复朱见深皇太子身份", "description": "天顺元年三月己巳，明英宗朱祁镇重新将长子朱见深立为皇太子。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年三月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a50d8de7-1dfa-57c6-b8db-aa619c2d9bf7"}, {"title": "明廷封朱见潾等四位皇子为亲王", "description": "天顺元年三月己巳，明廷封皇子朱见潾为德王、朱见澍为秀王、朱见泽为崇王、朱见浚为吉王。", "start_year": 1457, "end_year": 1457, "time_original": "天顺元年三月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7eb7247b-baa5-570d-bf8a-d10dec634af7"}, {"title": "徐有贞获封武功伯，兼华盖殿大学士，掌管文渊阁事务", "description": "景泰8年（1457年）三月，徐有贞获封武功伯，兼华盖殿大学士，掌管文渊阁事务。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）三月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_